"""``tools.trace_to_state`` on synthetic raw traces generated by the JAX engine.

``_engine_trace`` plays a scripted Roark fight through ``step`` and writes what
``tools/trace_battle.lua`` would record: a ``turn`` record at every turn boundary and
``hit``/``move_end`` records for each move in between (docs/tracing.md, "Raw trace
format"). The converter must recover every engine state, the actions and the realized
hits, crits and damage rolls.
"""

from __future__ import annotations

import copy
import itertools
import json
from pathlib import Path

import jax
import jax.numpy as jnp
import numpy as np
import pytest

from nuzline.data.party import load_party
from nuzline.data.trainer import IntermediateData, build_trainer_party, load_trainers
from nuzline.engine.damage import damage_for_roll
from nuzline.engine.ids import Status, Weather
from nuzline.engine.order import MOVE_ACTIONS, action_order, is_switch, selected_move
from nuzline.engine.outcome import Outcome, empty_outcome
from nuzline.engine.state import BattleState
from nuzline.engine.step import needs_replacement, replace, step
from tools.trace_to_state import (
    COMPARED_FIELDS,
    INTERMEDIATE,
    MOVE_STATUS_MISSED,
    STAGE_ORDER,
    AmbiguousTrace,
    TraceMismatch,
    bundle_trace,
    convert,
    decode_status,
    decode_weather,
    initial_state,
    main,
    resolve_roll,
    trace_to_states,
)

ROOT = Path(__file__).resolve().parents[1]
PARTY = ROOT / "tests" / "fixtures" / "golden_party_roark_01.toml"
ROARK_ID = 246
EMBER, MACH_PUNCH, BUBBLE, POUND = 2, 3, 2, 0  # move slots of Monferno / Prinplup
TO_PRINPLUP = MOVE_ACTIONS + 1
STEALTH_ROCK, ROCK_THROW, SCREECH = 0, 1, 2  # Geodude / Onix move slots
POTION = 10  # the opponent's bag slot 0

_step = jax.jit(step)


def _outcome(**hits) -> Outcome:
    """``empty_outcome`` with ``hit``/``crit``/``roll`` set per side: keywords
    ``p_roll``, ``p_crit``, ``p_hit``, ``o_roll``, ``o_crit``, ``o_hit``."""
    o = {name: np.asarray(v).copy() for name, v in empty_outcome()._asdict().items()}
    for key, value in hits.items():
        who, field = key.split("_")
        o[field][0 if who == "p" else 1, :] = value
    return Outcome(**{k: jnp.asarray(v) for k, v in o.items()})


# (actions, outcome) per turn: Monferno vs Geodude, a crit KO and Onix's replacement,
# a switch to Prinplup, a miss against Screech, a hit at -2 Defense, then Roark's Potion
# on the damaged Onix before Bubble knocks it out and Cranidos comes in.
SCRIPT = [
    ((EMBER, ROCK_THROW), _outcome(p_roll=4, o_roll=3)),
    ((MACH_PUNCH, ROCK_THROW), _outcome(p_roll=9, p_crit=1)),
    ((TO_PRINPLUP, ROCK_THROW), _outcome(o_roll=0)),
    ((BUBBLE, SCREECH), _outcome(p_hit=0)),
    ((POUND, ROCK_THROW), _outcome(p_roll=8, o_roll=15)),
    ((BUBBLE, POTION), _outcome(p_roll=2)),
]


def _raw_status(status: int, counter: int) -> int:
    bits = {
        Status.NONE: 0,
        Status.SLEEP: counter & 7,
        Status.POISON: 1 << 3,
        Status.BURN: 1 << 4,
        Status.FREEZE: 1 << 5,
        Status.PARALYSIS: 1 << 6,
        Status.TOXIC: (1 << 7) | ((counter & 0xF) << 8),
    }
    return bits[Status(status)]


def _stages(state: BattleState, side: int) -> list[int]:
    return [int(state.stages[side, stat]) + 6 for stat in STAGE_ORDER]


def _turn_record(state: BattleState, turn: int, command: int = 4) -> dict:
    sides = []
    for side in (0, 1):
        party = []
        for slot in range(6):
            if int(state.species[side, slot]) == 0:
                break
            party.append(
                {
                    "species": int(state.species[side, slot]),
                    "level": int(state.level[side, slot]),
                    "hp": int(state.hp[side, slot]),
                    "max_hp": int(state.max_hp[side, slot]),
                    "status": _raw_status(
                        int(state.status[side, slot]), int(state.status_counter[side, slot])
                    ),
                    "moves": [int(m) for m in state.moves[side, slot]],
                    "pp": [int(p) for p in state.pp[side, slot]],
                    "item": int(state.item[side, slot]),
                }
            )
        sides.append(
            {"active": int(state.active[side]), "stages": _stages(state, side), "party": party}
        )
    return {"kind": "turn", "turn": turn, "command": command, "rng": 0, "field": 0, "sides": sides}


def _move_events(tables, state, actions, outcome, turn) -> list[dict]:
    """The ``hit``/``move_end`` records of one turn, in execution order. Every scripted
    move either hits once or misses, and no hit changes a stage the later hit uses."""
    active = [int(state.active[0]), int(state.active[1])]
    stages = [_stages(state, 0), _stages(state, 1)]
    for side in (0, 1):
        if is_switch(actions[side]):
            active[side] = int(actions[side]) - MOVE_ACTIONS
            stages[side] = [6] * 8
    hp = {(side, active[side]): int(state.hp[side, active[side]]) for side in (0, 1)}
    events = []
    for side in np.asarray(action_order(tables, state, jnp.asarray(actions), outcome)).tolist():
        if actions[side] >= MOVE_ACTIONS:
            continue
        user, target = (side, active[side]), (1 - side, active[1 - side])
        if hp[user] == 0:
            continue  # fainted before moving
        move = int(selected_move(tables, state, side, actions[side])[0])
        missed = int(outcome.hit[side, 0]) == 0
        events.append(
            {
                "kind": "move_end",
                "turn": turn,
                "attacker": side,
                "move": move,
                "flags": MOVE_STATUS_MISSED if missed else 0,
            }
        )
        if missed or int(tables.move_power[move]) == 0:
            continue
        hit_state = state._replace(active=jnp.asarray(active, jnp.int8))
        crit = int(outcome.crit[side, 0])
        damage = int(
            damage_for_roll(tables, hit_state, side, move, crit != 0, outcome.roll[side, 0])
        )
        events.insert(
            len(events) - 1,
            {
                "kind": "hit",
                "turn": turn,
                "attacker": side,
                "defender": 1 - side,
                "move": move,
                "damage": damage,
                "crit": crit,
                "active": list(active),
                "hp": [hp[(0, active[0])], hp[(1, active[1])]],
                "status": [
                    _raw_status(
                        int(state.status[b, active[b]]), int(state.status_counter[b, active[b]])
                    )
                    for b in (0, 1)
                ],
                "stages": [list(stages[0]), list(stages[1])],
            },
        )
        hp[target] = max(hp[target] - damage, 0)
    return events


def _engine_trace(tables, names):
    """(raw records, engine states before each turn and after the last)."""
    trainer = next(t for t in load_trainers(INTERMEDIATE) if t.id == ROARK_ID)
    player = load_party(PARTY, names)
    state = initial_state(tables, player, trainer, (0, 0))
    records, states = [_turn_record(state, 0)], [state]
    for turn, (actions, outcome) in enumerate(SCRIPT):
        records += _move_events(tables, state, actions, outcome, turn)
        state = _step(tables, state, jnp.asarray(actions, jnp.int32), outcome)
        if needs_replacement(state)[1]:
            slot = int(np.flatnonzero(np.asarray(state.hp[1]) > 0)[0])
            state = replace(tables, state, 1, slot)
        records.append(_turn_record(state, turn + 1))
        states.append(state)
    records[-1]["command"] = 41  # the last record is written at BATTLE_CONTROL_RESULT
    return records, states


def _write_raw(path: Path, records: list[dict]) -> Path:
    path.write_text("".join(json.dumps(r) + "\n" for r in records), encoding="utf-8")
    return path


def _bundle(tmp_path: Path, names, records) -> Path:
    raw = _write_raw(tmp_path / "raw.jsonl", records)
    out = tmp_path / "bundle.json"
    out.write_text(json.dumps(bundle_trace(raw, PARTY, names, ROARK_ID)), encoding="utf-8")
    return out


@pytest.fixture(scope="module")
def engine_trace(tables, names):
    return _engine_trace(tables, names)


def _hits(records, side):
    return [r for r in records if r["kind"] == "hit" and r["attacker"] == side]


def test_synthetic_trace_round_trips(tables, names, engine_trace, tmp_path):
    records, states = engine_trace
    turns = convert(_bundle(tmp_path, names, records), tables, names)
    assert len(turns) == len(states)
    for i, (turn, expected) in enumerate(zip(turns, states)):
        for name in BattleState._fields:
            assert np.array_equal(getattr(turn.state, name), getattr(expected, name)), (
                f"turn {i} field {name}"
            )
        assert turn.mismatched == ()
    # Both sides acted on every scripted turn except turn 1, where Geodude fainted first.
    for i, (actions, outcome) in enumerate(SCRIPT):
        got = turns[i]
        if i != 1:
            assert got.actions == actions, f"turn {i}"
        for side in (0, 1):
            if (i, side) == (1, 1) or actions[side] >= MOVE_ACTIONS:
                continue
            assert int(got.outcome.hit[side, 0]) == int(outcome.hit[side, 0])
            assert int(got.outcome.crit[side, 0]) == int(outcome.crit[side, 0])
    assert turns[-1].actions == (-1, -1)


def test_recovered_turns_replay_like_the_golden_test(tables, names, engine_trace, tmp_path):
    records, _ = engine_trace
    turns = trace_to_states(_bundle(tmp_path, names, records), tables, names)
    for (before, actions, outcome), (after, _, _) in itertools.pairwise(turns):
        out = _step(tables, before, actions, outcome)
        if needs_replacement(out)[1]:
            out = replace(tables, out, 1, int(after.active[1]))
        for name in COMPARED_FIELDS:
            assert getattr(out, name).tolist() == getattr(after, name).tolist(), name


def test_rolls_with_equal_damage_are_recorded(tables, names, engine_trace, tmp_path):
    records, _ = engine_trace
    turns = convert(_bundle(tmp_path, names, records), tables, names)
    # Ember on Geodude does 12 for rolls 4-14 (damage_table), so all fit; the lowest is used.
    candidates = turns[0].roll_candidates[(0, 0)]
    assert candidates == [(0, r) for r in range(4, 15)]
    assert int(turns[0].outcome.roll[0, 0]) == 4


def test_damage_that_fits_no_roll_raises_trace_mismatch(tables, names, engine_trace, tmp_path):
    records = copy.deepcopy(engine_trace[0])
    _hits(records, 0)[0]["damage"] = 99
    with pytest.raises(TraceMismatch, match="damage 99"):
        convert(_bundle(tmp_path, names, records), tables, names)


def test_unknown_crit_is_resolved_when_only_one_fits(tables, names, engine_trace, tmp_path):
    records = copy.deepcopy(engine_trace[0])
    for hit in _hits(records, 0):
        hit["crit"] = None
    turns = convert(_bundle(tmp_path, names, records), tables, names)
    assert int(turns[0].outcome.crit[0, 0]) == 0
    assert int(turns[1].outcome.crit[0, 0]) == 1


def test_a_party_that_differs_from_the_trace_raises(tables, names, engine_trace, tmp_path):
    records = copy.deepcopy(engine_trace[0])
    records[0]["sides"][0]["party"][0]["level"] = 15
    with pytest.raises(TraceMismatch, match="level"):
        convert(_bundle(tmp_path, names, records), tables, names)


def test_the_trace_stops_at_the_first_player_faint(tables, names, engine_trace, tmp_path):
    records = copy.deepcopy(engine_trace[0])
    second_turn = [r for r in records if r["kind"] == "turn"][1]
    second_turn["sides"][0]["party"][0]["hp"] = 0  # Monferno faints on turn 0
    turns = convert(_bundle(tmp_path, names, records), tables, names)
    assert len(turns) == 2
    assert "hp" in turns[0].mismatched
    assert turns[1].actions == (-1, -1)


def test_cli_writes_a_bundle_that_converts(tables, names, engine_trace, tmp_path):
    raw = _write_raw(tmp_path / "raw.jsonl", engine_trace[0])
    out = tmp_path / "golden.json"
    assert main(["--trace", str(raw), "--out", str(out), "--party", str(PARTY)]) == 0
    bundle = json.loads(out.read_text(encoding="utf-8"))
    assert bundle["trainer_id"] == ROARK_ID
    assert len(trace_to_states(out, tables, names)) == len(SCRIPT) + 1


def test_resolve_roll_uses_the_lowest_of_equal_candidates():
    assert resolve_roll([(0, 7), (0, 3), (0, 5)]) == (0, 3)


def test_resolve_roll_refuses_when_a_crit_and_a_non_crit_both_fit():
    with pytest.raises(AmbiguousTrace) as err:
        resolve_roll([(0, 15), (1, 0)])
    assert err.value.candidates == [(0, 15), (1, 0)]


@pytest.mark.parametrize(
    ("raw", "expected"),
    [
        (0, (Status.NONE, 0)),
        (3, (Status.SLEEP, 3)),
        (1 << 3, (Status.POISON, 0)),
        (1 << 4, (Status.BURN, 0)),
        (1 << 5, (Status.FREEZE, 0)),
        (1 << 6, (Status.PARALYSIS, 0)),
        ((1 << 7) | (2 << 8), (Status.TOXIC, 2)),
    ],
)
def test_decode_status(raw, expected):
    assert decode_status(raw) == expected


@pytest.mark.parametrize(
    ("mask", "expected"),
    [
        (0, Weather.NONE),
        (1, Weather.RAIN),
        (1 << 3, Weather.SANDSTORM),
        (1 << 4, Weather.SUN),
        (1 << 7, Weather.HAIL),
        (1 << 15, Weather.FOG),
        (1 << 12, Weather.NONE),
    ],
)
def test_decode_weather(mask, expected):
    assert decode_weather(mask) == expected


def test_initial_state_uses_the_trainers_party_and_bag(tables, names):
    trainer = next(t for t in load_trainers(INTERMEDIATE) if t.id == ROARK_ID)
    state = initial_state(tables, load_party(PARTY, names), trainer, (0, 0))
    opp = build_trainer_party(trainer, IntermediateData(INTERMEDIATE))
    assert [int(s) for s in state.species[1, : len(opp)]] == [m.species for m in opp]
    assert [int(i) for i in state.trainer_items[1, :2]] == list(trainer.items)
